from urllib.parse import urlsplit


def tenant_label(url):
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    parts = urlsplit(url)
    if parts.scheme != "https" or parts.username is not None or parts.password is not None:
        raise ValueError("invalid URL")
    try:
        host = parts.hostname
        port = parts.port
    except ValueError as exc:
        raise ValueError("invalid URL") from exc
    if host is None or port is not None:
        raise ValueError("invalid URL")
    labels = host.split(".")
    if len(labels) < 3 or any(not label for label in labels):
        raise ValueError("host must have at least three labels")
    if any(not label.isascii() or not label.replace("-", "").isalnum() or label[0] == "-" or label[-1] == "-" for label in labels):
        raise ValueError("invalid host label")
    return labels[1].lower()
```

`tenant_label(url)` must return the lowercased leftmost hostname label from an absolute HTTPS URL. The URL must have no credentials or explicit port and its hostname must contain at least three non-empty ASCII alphanumeric-or-hyphen labels; no label may begin or end with a hyphen. Paths, queries, and fragments do not affect the result. Non-string input raises `TypeError`; every malformed URL raises `ValueError`.

